export const defaults=[{id:'guess',name:'Repeated password failures',threshold:10,minutes:5,technique:'T1110.001',priority:'Medium'},{id:'spray',name:'Failures across multiple accounts',threshold:8,minutes:10,technique:'T1110.003',priority:'Medium'},{id:'success',name:'Success after repeated failures',threshold:5,minutes:10,technique:'T1078',priority:'High'},{id:'invalid',name:'Repeated invalid-user attempts',threshold:5,minutes:10,technique:'T1110.001',priority:'Medium'}];
export const techniques={'T1110.001':{name:'Password Guessing',url:'https://attack.mitre.org/techniques/T1110/001/',description:'Repeated attempts to authenticate may resemble guessing credentials.',missing:'Failures alone do not establish malicious intent.'},'T1110.003':{name:'Password Spraying',url:'https://attack.mitre.org/techniques/T1110/003/',description:'Failures across accounts resemble broad account targeting.',missing:'Logs do not reveal whether the same password was tried across accounts.'},T1078:{name:'Valid Accounts',url:'https://attack.mitre.org/techniques/T1078/',description:'A successful authentication is context for investigating possible account misuse.',missing:'Successful authentication alone does not establish compromise.'}};
export const scenarios=[['mixed','Mixed authentication activity'],['normal','Normal login activity'],['guess','Password guessing / brute force'],['spray','Password spraying pattern'],['success','Success after repeated failures'],['invalid','Invalid-user enumeration'],['ddos','DDoS-like distributed HTTP flood'],['dos','Single-source HTTP flood'],['scan','Web path scanning / 404 burst'],['sql','SQL injection-like requests'],['traversal','Path traversal-like requests'],['errors','Server error burst (5xx)'],['all','Combined authentication & web incidents']];
const webRules=[{id:'ddos',name:'Distributed HTTP request burst',threshold:100,minutes:1,min_sources:10,technique:'T1499.003',priority:'High'}, {id:'dos',name:'Single-source HTTP request burst',threshold:60,minutes:1,technique:'T1499.003',priority:'High'}, {id:'scan',name:'Many missing web paths',threshold:10,minutes:5,technique:'T1595.002',priority:'Medium'}, {id:'sql',name:'SQL injection-like request patterns',threshold:3,minutes:5,technique:'T1190',priority:'High'}, {id:'traversal',name:'Path traversal-like request patterns',threshold:3,minutes:5,technique:'T1190',priority:'High'}, {id:'errors',name:'Server error burst',threshold:20,minutes:5,technique:'Operational',priority:'Medium'}];
defaults.push(...webRules);
Object.assign(techniques,{'T1499.003':{name:'Application Exhaustion Flood',url:'https://attack.mitre.org/techniques/T1499/003/',description:'A concentrated request burst resembles application flooding.',missing:'Volume alone cannot prove denial of service, coordination, or malicious intent. Source IPs do not establish unique devices. Resource exhaustion needs server metrics.'},'T1595.002':{name:'Vulnerability Scanning',url:'https://attack.mitre.org/techniques/T1595/002/',description:'Requests for many missing paths may reflect automated application probing.',missing:'A 404 burst does not prove vulnerability scanning; broken links or legitimate crawlers can produce it.'},T1190:{name:'Exploit Public-Facing Application',url:'https://attack.mitre.org/techniques/T1190/',description:'Suspicious request strings can resemble attempts to exploit a public application.',missing:'Pattern matching does not prove a vulnerability or successful exploitation. Encoded or novel payloads may evade these narrow rules.'},Operational:{name:'Service reliability signal',url:null,description:'Repeated server-side errors indicate a service issue needing review.',missing:'Errors alone do not establish an attack. Check deployment, database, and upstream service health.'}});
const csv=line=>{const out=[];let v='',q=false;for(let i=0;i<line.length;i++){let c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){v+='"';i++;}else q=!q;}else if(c===','&&!q){out.push(v);v='';}else v+=c;}if(q)throw Error('Multiline or unclosed CSV quote is unsupported');out.push(v);return out;};
export function parse(text,file='input.log',settings={}){
 if(text.includes('\0'))throw Error('Binary files are unsupported. Choose a UTF-8 text log.');
 const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/);const first=lines.find(l=>l.trim())||'';
 const format=settings.format&&settings.format!=='auto'?settings.format:first.trim().startsWith('{')?'jsonl':/timestamp.*,/i.test(first)?'csv':'ssh';
 let headers,events=[],unsupported=[],duplicates=0;const seen=new Set(),assumptions=new Set();
 function timestamp(value){let s=String(value||'');if(!/^\d{4}-\d\d-\d\d[T ]\d\d:\d\d:\d\d/.test(s))throw Error('Expected ISO 8601 timestamp');if(!/(Z|[+-]\d\d:\d\d)$/i.test(s)){if(!settings.offset)throw Error('Timezone context required');s+=settings.offset;assumptions.add('Naive timestamps use UTC offset '+settings.offset);}const date=new Date(s);if(!Number.isFinite(+date))throw Error('Invalid timestamp');return date.toISOString();}
 lines.forEach((raw,i)=>{if(!raw.trim())return;try{let e;if(format==='jsonl')e=JSON.parse(raw);else if(format==='csv'){const a=csv(raw);if(!headers){headers=a;return;}if(a.length!==headers.length)throw Error('CSV field count mismatch');e=Object.fromEntries(headers.map((h,j)=>[h,a[j]]));}else{
 const m=raw.match(/^(\w{3}\s+\d{1,2}\s+\d\d:\d\d:\d\d|\d{4}-\d\d-\d\dT\S+)\s+(\S+)\s+sshd(?:\[\d+\])?:\s+(.*)$/);if(!m)throw Error('Unrecognized SSH record');let ts=m[1];if(!/^\d{4}/.test(ts)){if(!settings.year||!settings.offset)throw Error('Year and UTC offset required');const a=ts.split(/\s+/);const month=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'].indexOf(a[0])+1;if(!month)throw Error('Invalid month');ts=`${settings.year}-${String(month).padStart(2,'0')}-${a[1].padStart(2,'0')}T${a[2]}${settings.offset}`;assumptions.add(`Syslog year ${settings.year}, UTC offset ${settings.offset}; split multi-year files before import.`);}
 const a=m[3].match(/^(Failed password|Accepted password|Accepted publickey) for (invalid user )?(\S+) from (\S+) port (\d+)/);const b=m[3].match(/^Invalid user (\S+) from (\S+)(?: port (\d+))?/);if(!a&&!b)throw Error('Unsupported OpenSSH message');e={timestamp:ts,hostname:m[2],action:a?(a[2]?'invalid_user':'login'):'invalid_user',outcome:a&&a[1].startsWith('Accepted')?'success':'failure',username:a?a[3]:b[1],source_ip:a?a[4]:b[2],source_port:a?a[5]:b[3]};}
 const action=e.event_type||e.action;if(!['login','invalid_user','http_request'].includes(action)||!['success','failure'].includes(e.outcome))throw Error('Expected action login/invalid_user/http_request and outcome success/failure');if(action==='http_request'&&(!Number.isInteger(Number(e.status_code))||Number(e.status_code)<100||Number(e.status_code)>599||typeof e.path!=='string'||!e.path.startsWith('/')))throw Error('HTTP events require status_code (100–599) and a path starting with /');if(action==='http_request'&&e.outcome!==(Number(e.status_code)>=400?'failure':'success'))throw Error('HTTP outcome must match status_code (400–599 failure, otherwise success)');const t=timestamp(e.timestamp_utc||e.timestamp);const key=raw;if(seen.has(key)){duplicates++;return;}seen.add(key);events.push({event_id:`e${i+1}`,timestamp_utc:t,original_timestamp:e.timestamp_utc||e.timestamp,hostname:e.hostname||null,source_type:format,event_type:action,outcome:e.outcome,username:e.username||null,source_ip:e.source_ip||null,source_port:e.source_port||null,status_code:action==='http_request'?Number(e.status_code):null,path:action==='http_request'?e.path:null,raw_line:raw,source_file:file,line_number:i+1});
 }catch(err){unsupported.push({line_number:i+1,raw_line:raw,reason:err.message});}});
 events.sort((a,b)=>a.timestamp_utc.localeCompare(b.timestamp_utc));return{events,unsupported,duplicates,format,file,assumptions:[...assumptions],parser_version:'1.1.0',nonempty_lines:lines.filter(l=>l.trim()).length};
}
export function analyze(events,rules=defaults){const findings=[];for(const rule of rules.filter(r=>!webRules.some(w=>w.id===r.id))){const groups=new Map();for(const e of events){if(e.event_type==='http_request'||!e.source_ip||!e.hostname||!e.username)continue;const key=JSON.stringify([e.source_ip,e.hostname,...(['guess','success'].includes(rule.id)?[e.username]:[])]);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(e);}for(const g of groups.values()){
 let clusters=[];for(let i=0,left=0;i<g.length;i++){while(+new Date(g[i].timestamp_utc)-+new Date(g[left].timestamp_utc)>rule.minutes*60000)left++;let win=g.slice(left,i+1),fails=win.filter(e=>e.outcome==='failure'&&(rule.id!=='invalid'||e.event_type==='invalid_user'));let measured=['spray','invalid'].includes(rule.id)?new Set(fails.map(e=>e.username)).size:fails.length;if(measured<rule.threshold||(rule.id==='success'&&g[i].outcome!=='success'))continue;let evidence=rule.id==='success'?[...fails,g[i]]:fails;let prev=clusters.at(-1);if(prev&&evidence.some(e=>prev.has(e.event_id))){evidence.forEach(e=>prev.set(e.event_id,e));}else clusters.push(new Map(evidence.map(e=>[e.event_id,e])));}
 for(const c of clusters){const evidence=[...c.values()].sort((a,b)=>a.timestamp_utc.localeCompare(b.timestamp_utc));const f=evidence[0];findings.push({id:`${rule.id}-${f.event_id}`,name:rule.name,priority:rule.priority,rule:{...rule,version:'1.0.0'},technique:techniques[rule.technique],mapping_version:'2026-09-24',events:evidence.map(e=>e.event_id),source_ip:f.source_ip,hostname:f.hostname,username:['spray','invalid'].includes(rule.id)?`${new Set(evidence.map(e=>e.username)).size} accounts`:f.username,start:f.timestamp_utc,end:evidence.at(-1).timestamp_utc,count:evidence.length,status:'New',notes:'',investigation:''});}
 }}findings.push(...analyzeWeb(events,rules));return findings.sort((a,b)=>(a.priority==='High'?-1:1)-(b.priority==='High'?-1:1)||a.start.localeCompare(b.start));}
function analyzeWeb(events,rules){const findings=[];for(const rule of rules.filter(r=>webRules.some(w=>w.id===r.id))){const groups=new Map();for(const e of events){if(e.event_type!=='http_request'||!e.hostname||!e.source_ip)continue;let path=e.path||'';try{path=decodeURIComponent(path);}catch{}const relevant=rule.id==='scan'?e.status_code===404:rule.id==='errors'?e.status_code>=500:rule.id==='sql'?/union\s+select|(?:'|")\s*or\s+1\s*=\s*1/i.test(path):rule.id==='traversal'?/\.\.\//.test(path):true;if(!relevant)continue;const key=JSON.stringify(['ddos','errors'].includes(rule.id)?[e.hostname]:[e.hostname,e.source_ip]);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(e);}
 for(const g of groups.values()){const clusters=[];for(let i=0,left=0;i<g.length;i++){while(+new Date(g[i].timestamp_utc)-+new Date(g[left].timestamp_utc)>rule.minutes*60000)left++;const win=g.slice(left,i+1),measured=rule.id==='scan'?new Set(win.map(e=>e.path.split('?')[0])).size:win.length;if(measured<rule.threshold||(rule.id==='ddos'&&new Set(win.map(e=>e.source_ip)).size<rule.min_sources))continue;const prev=clusters.at(-1);if(prev&&win.some(e=>prev.events.has(e.event_id))){win.forEach(e=>prev.events.set(e.event_id,e));prev.peak=Math.max(prev.peak,measured);}else clusters.push({events:new Map(win.map(e=>[e.event_id,e])),peak:measured});}
 for(const c of clusters){const ev=[...c.events.values()],ips=[...new Set(ev.map(e=>e.source_ip))];findings.push({id:rule.id+'-'+ev[0].event_id,name:rule.name,priority:rule.priority,rule:{...rule,version:'1.1.0'},technique:techniques[rule.technique],mapping_version:'2026-09-24',events:ev.map(e=>e.event_id),source_ip:ips.length===1?ips[0]:ips.length+' sources',source_ips:ips,hostname:ev[0].hostname,username:'HTTP traffic',start:ev[0].timestamp_utc,end:ev.at(-1).timestamp_utc,count:ev.length,peak:c.peak,status:'New',notes:'',investigation:''});}
 }}return findings;}
export function sample(kind='mixed'){if(!scenarios.some(([id])=>id===kind))throw Error('Unknown sample scenario');const start=Date.now()-3600000-Math.floor(Math.random()*3600000),data=[];const admin=['admin','deploy','operator'][Math.floor(Math.random()*3)];function add(s,user,ip,outcome='success',action='login'){data.push({timestamp:new Date(start+s*1000).toISOString(),action,outcome,username:user,source_ip:ip,hostname:'server-01'});}function http(s,ip,path,code=200){data.push({timestamp:new Date(start+s*1000).toISOString(),action:'http_request',outcome:code>=400?'failure':'success',source_ip:ip,hostname:'web-01',path,status_code:code});}
 const web=['ddos','dos','scan','sql','traversal','errors'].includes(kind);for(let i=0;i<64;i++){if(!web)add(i*45,['alice','marcus','ci-runner'][i%3],`192.0.2.${10+i%4}`);if(web||kind==='all')http(i*45,`192.0.2.${10+i%4}`,['/','/products','/health'][i%3]);}
 if(['guess','mixed','success','all'].includes(kind)){const n=12+Math.floor(Math.random()*15);for(let i=0;i<n;i++)add(900+i*6,admin,'192.0.2.44','failure');if(['success','mixed','all'].includes(kind))add(1080,admin,'192.0.2.44');}
 if(['spray','mixed','invalid','all'].includes(kind))for(let i=0;i<10+Math.floor(Math.random()*5);i++)add(1700+i*15,`user${i}`,'198.51.100.23','failure',kind==='invalid'||i<6?'invalid_user':'login');
 if(['ddos','all'].includes(kind))for(let i=0,n=150+Math.floor(Math.random()*60);i<n;i++)http(1200+i*.2,`203.0.113.${1+i%20}`,'/search',i%3?503:200);
 if(['dos','all'].includes(kind))for(let i=0,n=80+Math.floor(Math.random()*30);i<n;i++)http(1500+i*.3,'198.51.100.80','/api/report',i%2?429:200);
 if(['scan','all'].includes(kind))for(let i=0;i<18;i++)http(1900+i*3,'198.51.100.81',`/admin/probe-${i}`,404);
 if(['sql','all'].includes(kind))for(let i=0;i<6;i++)http(2100+i*5,'198.51.100.82',"/search?q="+encodeURIComponent("' OR 1=1 --")+'&attempt='+i,403);
 if(['traversal','all'].includes(kind))for(let i=0;i<6;i++)http(2300+i*5,'198.51.100.83','/download?file='+encodeURIComponent('../../example-config')+'&attempt='+i,403);
 if(['errors','all'].includes(kind))for(let i=0,n=30+Math.floor(Math.random()*10);i<n;i++)http(2500+i*2,`192.0.2.${20+i%3}`,'/api/orders',i%2?500:502);
 return data.sort((a,b)=>a.timestamp.localeCompare(b.timestamp)).map(e=>JSON.stringify(e)).join('\n');}
